    function createSyntheticDopplerCanvas(phaseAngle, intensityMult) {
      const canvas = document.createElement('canvas');
      canvas.width = 500;
      canvas.height = 500;
      const ctx = canvas.getContext('2d');
      const cx = 250 + Math.cos(phaseAngle) * 40;
      const cy = 250 + Math.sin(phaseAngle) * 30;
      const baseRadius = 180 * intensityMult;
      const grad = ctx.createRadialGradient(cx, cy, 5, cx, cy, baseRadius);
      grad.addColorStop(0, 'rgba(255, 0, 255, 0.85)');   
      grad.addColorStop(0.2, 'rgba(220, 38, 38, 0.8)');   
      grad.addColorStop(0.45, 'rgba(234, 88, 12, 0.75)'); 
      grad.addColorStop(0.7, 'rgba(217, 119, 6, 0.65)');  
      grad.addColorStop(0.85, 'rgba(37, 99, 235, 0.45)'); 
      grad.addColorStop(1, 'rgba(37, 99, 235, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(cx, cy, baseRadius, 0, Math.PI * 2);
      ctx.fill();
      return canvas.toDataURL();
    }
    let syntheticRadarOverlays = [];
    let radarPhase = 0;
    let currentIntensityMult = 1.0;
    function updateRadarOverlay(multiplier) {
      currentIntensityMult = multiplier;
      if (!isRadarActive) return;
      radarLayerGroup.clearLayers();
      if (multiplier < 0.1) return; 
      const dwarkaBounds = [
        [28.5700, 76.9700], 
        [28.6500, 77.0800]  
      ];
      const imgUrl = createSyntheticDopplerCanvas(radarPhase, currentIntensityMult);
      const radarOverlay = L.imageOverlay(imgUrl, dwarkaBounds, {
        opacity: 0.65,
        interactive: false
      });
      radarLayerGroup.addLayer(radarOverlay);
    }
    function startRadarAnimation() {
      if (radarAnimationTimer) clearInterval(radarAnimationTimer);
      radarAnimationTimer = setInterval(() => {
        if (!isRadarActive) return;
        radarPhase += 0.25;
        if (radarPhase > Math.PI * 2) radarPhase = 0;
        updateRadarOverlay(currentIntensityMult);
      }, 800);
    }
    function toggleDopplerRadar() {
      const btn = document.getElementById('btnRadarToggle');
      isRadarActive = !isRadarActive;
      if (isRadarActive) {
        btn.classList.add('active');
        btn.innerHTML = `<span class="radar-ping"></span> 📡 Doppler Radar Overlay (dBZ)`;
        updateRadarOverlay(currentIntensityMult);
        startRadarAnimation();
      } else {
        btn.classList.remove('active');
        btn.innerHTML = `📡 Enable Doppler Radar`;
        radarLayerGroup.clearLayers();
        if (radarAnimationTimer) clearInterval(radarAnimationTimer);
      }
    }
